results.js:
morse.watch('div[aria-label="Tools"]', tools => {
  if (tools.querySelector('[data-morse-save]')) return;
  tools.appendChild(morse.el('button', {
    type: 'button',
    'aria-label': 'Save PNG',
    title: 'Save as PNG',
    text: '💾',
    'data-morse-save': '',
    style: 'width:38px;height:38px;font:inherit;cursor:pointer;',
    on: {
      click: () => {
        const stage = document.querySelector('div.stage');
        const canvases = stage ? [...stage.querySelectorAll('canvas')] : [];
        if (!canvases.length) { morse.toast('Nothing to save'); return; }
        const out = document.createElement('canvas');
        out.width = canvases[0].width;
        out.height = canvases[0].height;
        const ctx = out.getContext('2d');
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, out.width, out.height);
        canvases.forEach(c => ctx.drawImage(c, 0, 0));
        const a = morse.el('a', { href: out.toDataURL('image/png'), download: 'sketch.png' });
        document.body.appendChild(a);
        a.click();
        a.remove();
        morse.toast('Saved sketch.png');
      }
    }
  }));
});

