results.js:
morse.watch('[aria-label="Tools"]', tools => {
  if (tools.querySelector('#morse-save-png')) return;
  const btn = morse.el('button', {
    id: 'morse-save-png',
    'aria-label': 'Save as PNG',
    title: 'Save as PNG',
    text: '💾',
    style: 'width:38px;height:38px;border:0;border-radius:8px;background:transparent;cursor:pointer;font-size:18px;display:flex;align-items:center;justify-content:center;',
    on: {
      click: () => {
        const canvases = document.querySelectorAll('#board');
        const src = document.getElementById('board');
        if (!src) { morse.toast('No drawing found'); return; }
        const out = document.createElement('canvas');
        out.width = src.width;
        out.height = src.height;
        const ctx = out.getContext('2d');
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, out.width, out.height);
        ctx.drawImage(src, 0, 0);
        out.toBlob(blob => {
          if (!blob) { morse.toast('Could not create PNG'); return; }
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = 'sketch.png';
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(() => URL.revokeObjectURL(a.href), 1000);
          morse.toast('Saved sketch.png');
        }, 'image/png');
      }
    }
  });
  tools.appendChild(btn);
});

