results.js:
morse.watch('body > div.mn > h1', h1 => {
  if (h1.dataset.csvAdded) return;
  h1.dataset.csvAdded = '1';
  h1.style.display = 'flex';
  h1.style.alignItems = 'center';
  const btn = morse.el('button', {
    class: 'morse-csv-btn',
    text: 'Export CSV',
    on: {
      click: () => {
        const rows = [['Order', 'Customer', 'Date', 'Status', 'Amount']];
        document.querySelectorAll('div.tbl table tbody tr').forEach(tr => {
          rows.push([...tr.querySelectorAll('td')].map(td => {
            const v = td.textContent.trim().replace(/"/g, '""');
            return /[",\n]/.test(v) ? `"${v}"` : v;
          }));
        });
        const csv = rows.map(r => r.join(',')).join('\n');
        const a = morse.el('a', {
          href: URL.createObjectURL(new Blob([csv], { type: 'text/csv' })),
          download: 'orders.csv'
        });
        document.body.appendChild(a);
        a.click();
        a.remove();
        morse.toast('Exported orders.csv');
      }
    }
  });
  h1.appendChild(btn);
});

function exportCsv(tbl) {
  const rows = [...tbl.querySelectorAll('tr')].map(tr =>
    [...tr.children].map(c => '"' + c.textContent.trim().replace(/"/g, '""') + '"').join(',')
  );
  const blob = new Blob([rows.join('\n')], { type: 'text/csv' });
  const a = morse.el('a', { href: URL.createObjectURL(blob), download: 'recent-orders.csv' });
  document.body.appendChild(a);
  a.click();
  a.remove();
  morse.toast('Exported ' + (rows.length - 1) + ' orders');
}

