results.js:
morse.watch('div.tbl', tbl => {
  if (tbl.querySelector('.morse-search')) return;
  const input = morse.el('input', {
    class: 'morse-search',
    type: 'search',
    placeholder: 'Search orders, customers, status…',
    'aria-label': 'Search orders'
  });
  const sc = tbl.querySelector('div.sc');
  if (!sc) return;
  tbl.insertBefore(input, sc);
  const filter = () => {
    const q = input.value.trim().toLowerCase();
    tbl.querySelectorAll('table tbody tr').forEach(tr => {
      const match = !q || tr.textContent.toLowerCase().includes(q);
      tr.classList.toggle('morse-hidden', !match);
    });
  };
  morse.on(input, 'input', filter);
});

morse.watch('div.tbl > h3', h => {
  if (h.nextElementSibling && h.nextElementSibling.classList.contains('morse-search')) return;
  const input = morse.el('input', { class: 'morse-search', type: 'search', placeholder: 'Search orders…' });
  morse.on(input, 'input', () => {
    const q = input.value.trim().toLowerCase();
    document.querySelectorAll('div.tbl table tbody tr').forEach(tr => {
      tr.style.display = !q || tr.textContent.toLowerCase().includes(q) ? '' : 'none';
    });
  });
  h.after(input);
});

