results.js:
morse.watch("div.sc table thead th.am", th => {
  if (th.dataset.sortable) return;
  th.dataset.sortable = "1";
  th.style.cursor = "pointer";
  th.style.userSelect = "none";
  let dir = 1;
  morse.on(th, "click", () => {
    const table = th.closest("table");
    const tbody = table.querySelector("tbody");
    const idx = th.cellIndex;
    const rows = Array.from(tbody.querySelectorAll("tr"));
    rows.sort((a, b) => {
      const x = parseFloat(a.cells[idx].textContent.replace(/[^0-9.\-]/g, "")) || 0;
      const y = parseFloat(b.cells[idx].textContent.replace(/[^0-9.\-]/g, "")) || 0;
      return (x - y) * dir;
    });
    dir = -dir;
    rows.forEach(r => tbody.appendChild(r));
    morse.toast(dir === -1 ? "Sorted ascending" : "Sorted descending");
  });
});

