results.js:
morse.watch('th.am', th => {
  if (th.dataset.sortBound) return;
  th.dataset.sortBound = '1';
  morse.on(th, 'click', () => {
    const tbody = th.closest('table').tBodies[0];
    const idx = th.cellIndex;
    const asc = th.dataset.dir !== 'asc';
    th.dataset.dir = asc ? 'asc' : 'desc';
    const val = r => parseFloat(String(r.cells[idx]?.textContent || '').replace(/[^0-9.\-]/g, '')) || 0;
    const rows = Array.from(tbody.rows);
    rows.sort((a, b) => asc ? val(a) - val(b) : val(b) - val(a));
    rows.forEach(r => tbody.appendChild(r));
  });
});

morse.watch('th.am', th => {
  let asc = false;
  morse.on(th, 'click', () => {
    const table = th.closest('table');
    const tbody = table.querySelector('tbody');
    const idx = Array.from(th.parentNode.children).indexOf(th);
    const val = r => parseFloat((r.children[idx]?.textContent || '').replace(/[^0-9.\-]/g, '')) || 0;
    asc = !asc;
    const rows = Array.from(tbody.querySelectorAll('tr'));
    rows.sort((a, b) => asc ? val(a) - val(b) : val(b) - val(a));
    rows.forEach(r => tbody.appendChild(r));
    th.textContent = 'Amount ' + (asc ? '▲' : '▼');
  });
});

