results.js:
morse.watch('div.tbl .sc table', table => {
  if (table.querySelector('tfoot[data-total]')) return;
  const sum = [...table.querySelectorAll('tbody td.am')]
    .reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0);
  const tfoot = morse.el('tfoot', { 'data-total': '' },
    morse.el('tr', {},
      morse.el('td', { colspan: '4', text: 'Total' }),
      morse.el('td', { class: 'am', text: sum.toFixed(2) })
    )
  );
  table.appendChild(tfoot);
});

morse.watch('div.tbl table', table => {
  if (table.querySelector('tfoot.mod-total')) return;
  const sum = () => [...table.querySelectorAll('tbody td.am')]
    .reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0)
    .toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const cell = morse.el('td', { class: 'am', text: sum() });
  const tf = morse.el('tfoot', { class: 'mod-total' },
    morse.el('tr', {}, morse.el('td', { colspan: '4', text: 'Total' }), cell));
  table.appendChild(tf);
  morse.every(1000, () => { cell.textContent = sum(); });
});

const fmt = n => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

function ensureTotal(t) {
  let tf = t.querySelector('tfoot[data-mod-total]');
  if (!tf) {
    tf = morse.el('tfoot', { 'data-mod-total': '' },
      morse.el('tr', {},
        morse.el('td', { colspan: '4', text: 'Total' }),
        morse.el('td', { class: 'am', text: '0', 'data-mod-sum': '' })
      )
    );
    t.appendChild(tf);
  }
  const sum = [...t.querySelectorAll('tbody td.am')]
    .reduce((s, td) => s + (parseFloat(td.textContent) || 0), 0);
  const cell = tf.querySelector('[data-mod-sum]');
  if (cell) cell.textContent = fmt(sum);
}

morse.watch('.tbl table', ensureTotal);
morse.every(500, () => document.querySelectorAll('.tbl table').forEach(ensureTotal));

