results.js:
morse.watch('#pv', frame => {
  const darken = () => {
    try {
      const d = frame.contentDocument;
      if (!d || d.getElementById('morse-dark')) return;
      d.documentElement.style.colorScheme = 'dark';
      const s = d.createElement('style');
      s.id = 'morse-dark';
      s.textContent = 'html,body{background:#0f172a!important;color:#e2e8f0!important}';
      (d.head || d.documentElement).appendChild(s);
    } catch (e) {}
  };
  darken();
  morse.on(frame, 'load', darken);
});

morse.watch('#pv', el => {
  const apply = () => {
    try {
      const doc = el.contentDocument;
      if (!doc || !doc.head || doc.getElementById('morse-dark')) return;
      const s = doc.createElement('style');
      s.id = 'morse-dark';
      s.textContent =
        'html,body{background:#0f172a!important;color:#e2e8f0!important}' +
        'a{color:#93c5fd!important}';
      doc.head.appendChild(s);
    } catch (e) {}
  };
  apply();
  morse.on(el, 'load', apply);
});

