});

morse.watch("#pv", function (f) {
  function hide() {
    var d = f.contentDocument;
    if (!d || !d.head || d.getElementById("morse-hide-cookies")) return;
    var s = d.createElement("style");
    s.id = "morse-hide-cookies";
    s.textContent = '[id*="cookie" i],[class*="cookie" i],[aria-label*="cookie" i],[role="dialog"][aria-label*="consent" i]{display:none !important}';
    d.head.appendChild(s);
  }
  hide();
  morse.on(f, "load", hide);
});

morse.watch('#pv', frame => {
  const hide = () => {
    const doc = frame.contentDocument;
    if (!doc || doc.getElementById('morse-hide-cookie')) return;
    const s = doc.createElement('style');
    s.id = 'morse-hide-cookie';
    s.textContent = '[class*="cookie" i],[id*="cookie" i],[aria-label*="cookie" i]{display:none !important}';
    doc.head.appendChild(s);
  };
  morse.on(frame, 'load', hide);
  hide();
});

morse.watch('#pv', frame => {
  const grow = () => {
    try {
      const doc = frame.contentDocument;
      if (!doc || !doc.body) return;
      const targets = [];
      doc.querySelectorAll('body *').forEach(el => {
        const hasText = [...el.childNodes].some(n => n.nodeType === 3 && n.textContent.trim());
        if (hasText && !el.dataset.morseBig) targets.push(el);
      });
      // Read every size before writing any, so nested text isn't scaled twice.
      const sizes = targets.map(el => parseFloat(getComputedStyle(el).fontSize));
      targets.forEach((el, i) => {
        el.dataset.morseBig = '1';
        el.style.setProperty('font-size', (sizes[i] * 1.25) + 'px', 'important');
      });
    } catch (e) {
      morse.toast('The preview text can only be resized when the preview is on this site.');
    }
  };
  morse.on(frame, 'load', grow);
  grow();
});

morse.watch('#pv', el => {
  const grow = () => {
    try {
      const doc = el.contentDocument;
      if (doc && doc.body) doc.body.style.zoom = '1.25';
    } catch (e) {}
  };
  morse.on(el, 'load', grow);
  grow();
});

