results.js:
morse.watch('.wt tbody td.n', el => {
  const prev = el.previousElementSibling;
  if (!prev || prev.tagName !== 'TD' || prev.classList.contains('n')) return;
  const pop = parseInt(el.textContent.replace(/[,\s]/g, ''), 10);
  if (pop > 1000000) {
    const row = el.closest('tr');
    if (row) row.setAttribute('data-big', '1');
  }
});

morse.watch('td.n', el => {
  // Only the first numeric cell in each row is the population column
  if (el.previousElementSibling && el.previousElementSibling.matches('td.n')) return;
  const pop = parseInt(el.textContent.replace(/[^0-9]/g, ''), 10);
  if (!(pop >= 1000000)) return;
  const row = el.closest('tr');
  row.style.setProperty('background', 'rgb(255, 243, 205)', 'important');
  row.style.setProperty('font-weight', '700', 'important');
});

morse.watch('table.wt tbody tr', tr => {
  const table = tr.closest('table');
  const heads = [...table.rows[0].cells].map(c => c.textContent.trim().toLowerCase());
  const idx = heads.findIndex(h => h.startsWith('population'));
  if (idx < 0 || !tr.cells[idx]) return;
  const n = parseInt(tr.cells[idx].textContent.replace(/\D/g, ''), 10);
  if (n > 1000000) {
    tr.style.background = '#fff3c4';
    tr.style.fontWeight = '600';
  }
});

