results.js:
morse.on(document, 'keydown', e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key !== 'j' && e.key !== 'k') return;
  const t = e.target;
  if (t && t.closest && t.closest('input, textarea, [contenteditable="true"]')) return;
  const rows = [...document.querySelectorAll('section[aria-label="Message list"] [role="option"][data-i]')];
  if (!rows.length) return;
  const i = rows.findIndex(r => r.getAttribute('aria-selected') === 'true');
  const n = e.key === 'j'
    ? Math.min(rows.length - 1, i + 1)
    : Math.max(0, i - 1);
  const next = rows[n];
  e.preventDefault();
  next.click();
  next.scrollIntoView({ block: 'nearest' });
});

morse.on(document, "keydown", e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  if (e.key !== "j" && e.key !== "k") return;
  const rows = Array.from(document.querySelectorAll('section[aria-label="Message list"] div.r9[data-i]'));
  if (!rows.length) return;
  const cur = rows.findIndex(r => r.getAttribute("aria-selected") === "true");
  const next = e.key === "j" ? Math.min(rows.length - 1, cur + 1) : Math.max(0, cur < 0 ? 0 : cur - 1);
  const target = rows[next];
  if (!target || next === cur) return;
  e.preventDefault();
  target.click();
  target.scrollIntoView({ block: "nearest" });
  target.focus?.();
});

(() => {
  const items = () => [...document.querySelectorAll('section[aria-label="Message list"] [role="option"][data-i]')];
  const move = (dir) => {
    const list = items();
    if (!list.length) return;
    let idx = list.findIndex(el => el.getAttribute('aria-selected') === 'true');
    const next = Math.min(list.length - 1, Math.max(0, idx + dir));
    if (next === idx) return;
    const target = list[next];
    target.click();
    target.scrollIntoView({ block: 'nearest' });
    target.focus();
  };
  morse.on(document, 'keydown', e => {
    const t = e.target;
    if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
    if (e.metaKey || e.ctrlKey || e.altKey) return;
    if (e.key === 'j') { e.preventDefault(); move(1); }
    else if (e.key === 'k') { e.preventDefault(); move(-1); }
  });
  morse.toast('Use J and K to move through the email list');
})();

