morse.watch('input[aria-label="Search mail"]', input => {
  if (input.dataset.liveSearch) return;
  input.dataset.liveSearch = '1';
  const applyFilter = () => {
    const q = input.value.trim().toLowerCase();
    document.querySelectorAll('section[aria-label="Message list"] div.r9[data-i]').forEach(row => {
      const text = row.textContent.toLowerCase();
      row.style.display = !q || text.includes(q) ? '' : 'none';
    });
  };
  morse.on(input, 'input', applyFilter);
});

let query = "";

const matches = (row, term) => !term || row.textContent.toLowerCase().includes(term);

const applyFilter = () => {
  const term = query.trim().toLowerCase();
  document.querySelectorAll('section[aria-label="Message list"] [role="option"]').forEach(row => {
    row.style.display = matches(row, term) ? "" : "none";
  });
};

morse.watch('input[aria-label="Search mail"]', input => {
  morse.on(input, "input", () => {
    query = input.value;
    applyFilter();
  });
});

morse.watch('section[aria-label="Message list"] [role="option"]', row => {
  const term = query.trim().toLowerCase();
  if (term) row.style.display = matches(row, term) ? "" : "none";
});

morse.watch('input[aria-label="Search mail"]', input => {
  if (input.dataset.liveFilter) return;
  input.dataset.liveFilter = '1';
  const apply = () => {
    const q = input.value.trim().toLowerCase();
    document.querySelectorAll('section[aria-label="Message list"] div.r9[data-i]').forEach(row => {
      const text = row.textContent.toLowerCase();
      row.style.display = !q || text.includes(q) ? '' : 'none';
    });
  };
  morse.on(input, 'input', apply);
});

morse.watch('section[aria-label="Message list"] [role="option"][data-unread="true"]', () => {
  const update = () => {
    const n = document.querySelectorAll('[role="option"][data-unread="true"]').length;
    const base = document.title.replace(/^\(\d+\)\s*/, '');
    document.title = n > 0 ? `(${n}) ${base}` : base;
  };
  update();
  if (!window.__morseUnreadObs) {
    window.__morseUnreadObs = new MutationObserver(update);
    window.__morseUnreadObs.observe(document.body, { subtree: true, childList: true, attributes: true, attributeFilter: ['data-unread'] });
  }
});

morse.watch('div.r9[data-unread="true"]', () => {
  const n = document.querySelectorAll('div.r9[data-unread="true"]').length;
  document.title = n > 0 ? `(${n}) Inbox - Postbox` : 'Inbox - Postbox';
});

morse.watch('div.r9[data-unread="true"]', () => {
  const update = () => {
    const n = document.querySelectorAll('div.r9[data-unread="true"]').length;
    document.title = (n > 0 ? `(${n}) ` : '') + 'Inbox - Postbox';
  };
  update();
});
morse.every(2000, () => {
  const n = document.querySelectorAll('div.r9[data-unread="true"]').length;
  const base = 'Inbox - Postbox';
  const want = (n > 0 ? `(${n}) ` : '') + base;
  if (document.title !== want) document.title = want;
});

