results.js:
morse.watch('div[aria-label="Formatting"]', fmt => {
  if (fmt.querySelector('[data-morse-date]')) return;
  const btn = morse.el('button', {
    title: "Insert today's date",
    'data-morse-date': '',
    text: 'Date',
    on: {
      click: () => {
        const d = new Date();
        const today = d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        const ed = document.querySelector('div[role="textbox"]');
        if (!ed) return morse.toast('No editor found');
        ed.focus();
        const sel = window.getSelection();
        if (sel && sel.rangeCount && ed.contains(sel.anchorNode)) {
          document.execCommand('insertText', false, today);
        } else {
          ed.append(document.createTextNode(today));
        }
      }
    }
  });
  fmt.append(btn);
});

morse.watch('div[aria-label="Formatting"]', fmt => {
  const btn = morse.el('button', {
    title: "Insert today's date",
    text: 'Date',
    on: {
      // Keep the caret in the editor when the button is pressed
      mousedown: e => e.preventDefault(),
      click: () => {
        const box = document.querySelector('div[role="textbox"]');
        if (!box) return;
        const text = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        box.focus();
        if (!document.execCommand('insertText', false, text)) {
          box.appendChild(morse.el('p', { text }));
        }
      }
    }
  });
  fmt.appendChild(btn);
});

