morse.watch('.ed_9f', el => {
  let badge = el.parentElement.querySelector('.wc-live');
  if (!badge) {
    badge = morse.el('div', {
      class: 'wc-live',
      style: 'font-size:12px;color:rgb(155,154,151);margin-top:12px;font-family:inherit;'
    });
    el.insertAdjacentElement('afterend', badge);
  }
  const update = () => {
    const words = (el.innerText || '').trim().split(/\s+/).filter(Boolean).length;
    badge.textContent = words + (words === 1 ? ' word' : ' words');
  };
  update();
  morse.on(el, 'input', update);
});

