  var counter = document.querySelector('div.pg > div.doc > div.in');
  var badge = morse.el('div', {
    class: 'wc_live',
    style: 'font-size: 12px; color: rgb(155, 154, 151); margin-top: 8px; font-family: inherit;',
    text: '0 words'
  });
  ed.parentNode.insertBefore(badge, ed.nextSibling);

  function update() {
    var text = (ed.innerText || '').trim();
    var words = text ? text.split(/\s+/).length : 0;
    badge.textContent = words + (words === 1 ? ' word' : ' words');
