  const lines = [];
  document.querySelectorAll('section[aria-label="Conversation"] div.msg[data-role]').forEach(m => {
    const who = m.dataset.role === 'user' ? 'You' : 'Assistant';
    lines.push(`**${who}:** ${m.innerText.trim()}`, '');
  });
