const sortByPrice = (grid) => {
  const priceOf = (card) => {
    const m = card.textContent.match(/\$\s*([\d,]+(?:\.\d{1,2})?)/);
    return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
  };
  const items = Array.from(grid.children);
  items.sort((a, b) => priceOf(a) - priceOf(b) || 0);
  grid.append(...items);
  morse.toast("Sorted by price, lowest first");
};

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", (bar) => {
