    on: { click: sortByPrice }
  }));
});

function sortByPrice() {
  const list = document.querySelector('#__next > div:nth-of-type(2) > main > div:nth-of-type(2)');
  if (!list) return;
  const priceOf = el => {
    const m = el.textContent.match(/\$\s*([\d,]+(?:\.\d+)?)/);
