results.js:
function priceOf(el) {
  var m = (el.textContent || "").match(/\$\s?([\d,]+(?:\.\d+)?)/);
  return m ? parseFloat(m[1].replace(/,/g, "")) : Infinity;
}

function sortByPrice() {
  var list = document.querySelector("#__next > div:nth-of-type(2) > main > div:nth-of-type(2)");
  if (!list) return;
  var items = Array.from(list.children);
  items.sort(function (a, b) {
    var pa = priceOf(a), pb = priceOf(b);
    return pa === pb ? 0 : (pa < pb ? -1 : 1);
  });
  items.forEach(function (el) { list.appendChild(el); });
  morse.toast("Sorted by price, lowest first");
}

morse.watch("#__next > div:nth-of-type(2) > main > div:nth-of-type(1)", function (header) {
  header.appendChild(morse.el("button", {
    class: "morse-sort",
    text: "Sort: price low to high",
    on: { click: sortByPrice }
  }));
});

