results.js:
morse.watch('div[data-testid="player-controls"] .btns', (btns) => {
  if (btns.querySelector('.sleep-timer')) return;
  const minutes = [0, 15, 30, 60];
  let index = Number(morse.store.get('sleepIndex') || 0);
  let timeoutId = null;
  const label = () => (index === 0 ? 'Sleep' : `${minutes[index]}m`);
  const btn = morse.el('button', {
    class: 'sleep-timer',
    text: label(),
    title: 'Sleep timer',
    'aria-label': 'Sleep timer',
    on: {
      click: () => {
        index = (index + 1) % minutes.length;
        morse.store.set('sleepIndex', index);
        clearTimeout(timeoutId);
        timeoutId = null;
        btn.textContent = label();
        btn.classList.toggle('active', index !== 0);
        if (index === 0) {
          morse.toast('Sleep timer off');
          return;
        }
        const ms = minutes[index] * 60 * 1000;
        timeoutId = setTimeout(() => {
          const pause = document.querySelector('button[data-testid="play-pause"][aria-label="Pause"]');
          if (pause) pause.click();
          morse.toast('Sleep timer: playback paused');
          index = 0;
          btn.textContent = label();
          btn.classList.remove('active');
          morse.store.set('sleepIndex', 0);
        }, ms);
        morse.toast(`Sleep timer set for ${minutes[index]} minutes`);
      }
    }
  });
  if (index !== 0) btn.classList.add('active');
  btns.appendChild(btn);
});

