    const pp = document.querySelector('button[data-testid="play-pause"]');
    if (!pp) return;
    btn.disabled = true;
    morse.toast('Playback will pause in 15 minutes');
    setTimeout(() => {
      if (pp.getAttribute('aria-label') === 'Pause') pp.click();
      btn.disabled = false;
      btn.textContent = 'Sleep 15m';
    }, 15 * 60 * 1000);
    btn.textContent = 'Sleep on';
  } } });
  btns.appendChild(btn);
});

morse.watch('[data-testid="player-controls"] .btns', btns => {
  const steps = [0, 15, 30, 60];
  let idx = 0, endAt = 0;
  const btn = morse.el('button', {
    class: 'sleep-timer', 'aria-label': 'Sleep timer', title: 'Sleep timer', text: '☾',
    on: { click: () => {
      idx = (idx + 1) % steps.length;
      endAt = steps[idx] ? Date.now() + steps[idx] * 60000 : 0;
      btn.textContent = steps[idx] ? '☾ ' + steps[idx] + 'm' : '☾';
      morse.toast(steps[idx] ? 'Sleep in ' + steps[idx] + ' min' : 'Sleep timer off');
    }}
  });
  btns.appendChild(btn);
  morse.every(1000, () => {
    if (!endAt || Date.now() < endAt) return;
    endAt = 0; idx = 0; btn.textContent = '☾';
    const pp = document.querySelector('button[data-testid="play-pause"]');
    if (pp && pp.getAttribute('aria-label') === 'Pause') pp.click();
    morse.toast('Sleep timer: playback paused');
  });
});

morse.on(document, 'keydown', e => {
  if (e.key !== ' ' && e.code !== 'Space') return;
  if (e.repeat || e.ctrlKey || e.metaKey || e.altKey) return;
  const t = e.target;
  if (t && (t.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName))) return;
  const btn = document.querySelector('button[data-testid="play-pause"]');
  if (!btn || t === btn) return;
  e.preventDefault();
  btn.click();
});

