results.js:
morse.watch("#where", h => {
  if (h.parentElement.querySelector("#morse-all-off")) return;
  h.parentElement.style.display = "flex";
  h.parentElement.style.alignItems = "center";
  const btn = morse.el("button", {
    id: "morse-all-off",
    text: "All off",
    on: {
      click: () => {
        document.querySelectorAll("device-card").forEach(card => {
          if (card.getAttribute("state") === "on") {
            card.setAttribute("state", "off");
            card.dispatchEvent(new CustomEvent("toggle", { bubbles: true }));
          }
        });
        morse.toast("All devices turned off");
      }
    }
  });
  h.insertAdjacentElement("afterend", btn);
});

