morse.every(400, () => {
  const walk = root => {
    root.querySelectorAll('button[role="tab"]').forEach(el => {
      if (el.textContent.trim() === 'Living room') el.textContent = 'Lounge';
    });
    root.querySelectorAll('*').forEach(n => { if (n.shadowRoot) walk(n.shadowRoot); });
  };
  walk(document);
});

const renameTab = root => {
  root.querySelectorAll('button[role="tab"]').forEach(el => {
    if (el.textContent.trim() === 'Living room') el.textContent = 'Lounge';
  });
  root.querySelectorAll('*').forEach(n => { if (n.shadowRoot) renameTab(n.shadowRoot); });
};
morse.watch('hearth-bar', host => { if (host.shadowRoot) renameTab(host.shadowRoot); });
